 17	    public Database(String dbUrl, String dbUser, String dbPassword) {
 18	        HikariConfig config = new HikariConfig();
 19	        config.setJdbcUrl(dbUrl);
 20	        config.setUsername(dbUser);
 21	        config.setPassword(dbPassword);
 22	        config.setMaximumPoolSize(10);
 23	        config.setConnectionTimeout(30000);
 24	        config.setIdleTimeout(600000);
 25	        config.setMaxLifetime(1800000);
 26	
 27	        this.dataSource = new HikariDataSource(config);
 28	        initializeDatabase();
 29	    }
