 31	    private void initializeDatabase() {
 32	        try (Connection conn = dataSource.getConnection()) {
 33	            conn.setAutoCommit(false);
 34	
 35	            try (Statement stmt = conn.createStatement()) {
 36	                stmt.execute("""
 37	                    CREATE TABLE IF NOT EXISTS rooms (
 38	                        number INTEGER PRIMARY KEY,
 39	                        type VARCHAR(20) NOT NULL,
 40	                        capacity INTEGER NOT NULL,
 41	                        nightly_rate NUMERIC(10, 2) NOT NULL
 42	                    )
 43	                    """);
 44	
 45	                stmt.execute("""
 46	                    CREATE TABLE IF NOT EXISTS reservations (
 47	                        id BIGSERIAL PRIMARY KEY,
 48	                        room_number INTEGER NOT NULL,
 49	                        guest_name VARCHAR(255) NOT NULL,
 50	                        guest_email VARCHAR(255) NOT NULL,
 51	                        guest_cpf VARCHAR(14) NOT NULL,
 52	                        check_in DATE NOT NULL,
 53	                        check_out DATE NOT NULL,
 54	                        guests INTEGER NOT NULL,
 55	                        rate_plan VARCHAR(20) NOT NULL,
 56	                        nights INTEGER NOT NULL,
 57	                        subtotal NUMERIC(10, 2) NOT NULL,
 58	                        discount NUMERIC(10, 2) NOT NULL,
 59	                        total NUMERIC(10, 2) NOT NULL,
 60	                        status VARCHAR(20) NOT NULL,
 61	                        amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 62	                        refund NUMERIC(10, 2),
 63	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
 64	                    )
 65	                    """);
 66	
 67	                stmt.execute("""
 68	                    CREATE TABLE IF NOT EXISTS messages (
 69	                        id BIGSERIAL PRIMARY KEY,
 70	                        channel VARCHAR(20) NOT NULL,
 71	                        "to" VARCHAR(255) NOT NULL,
 72	                        subject VARCHAR(255) NOT NULL,
 73	                        body TEXT NOT NULL
 74	                    )
 75	                    """);
 76	
 77	                // Insert predefined rooms
 78	                try (PreparedStatement ps = conn.prepareStatement(
 79	                    "SELECT COUNT(*) as count FROM rooms")) {
 80	                    try (ResultSet rs = ps.executeQuery()) {
 81	                        if (rs.next() && rs.getInt("count") == 0) {
 82	                            insertPredefinedRooms(conn);
 83	                        }
 84	                    }
 85	                }
 86	            }
 87	
 88	            conn.commit();
 89	        } catch (SQLException e) {
 90	            throw new RuntimeException("Failed to initialize database", e);
 91	        }
 92	    }
