 94	    private void insertPredefinedRooms(Connection conn) throws SQLException {
 95	        String sql = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?)";
 96	        try (PreparedStatement ps = conn.prepareStatement(sql)) {
 97	            ps.setInt(1, 101);
 98	            ps.setString(2, "STANDARD");
 99	            ps.setInt(3, 2);
100	            ps.setBigDecimal(4, new BigDecimal("249.90"));
101	            ps.addBatch();
102	
103	            ps.setInt(1, 102);
104	            ps.setString(2, "STANDARD");
105	            ps.setInt(3, 2);
106	            ps.setBigDecimal(4, new BigDecimal("249.90"));
107	            ps.addBatch();
108	
109	            ps.setInt(1, 201);
110	            ps.setString(2, "DELUXE");
111	            ps.setInt(3, 3);
112	            ps.setBigDecimal(4, new BigDecimal("389.90"));
113	            ps.addBatch();
114	
115	            ps.setInt(1, 202);
116	            ps.setString(2, "DELUXE");
117	            ps.setInt(3, 3);
118	            ps.setBigDecimal(4, new BigDecimal("389.90"));
119	            ps.addBatch();
120	
121	            ps.setInt(1, 301);
122	            ps.setString(2, "SUITE");
123	            ps.setInt(3, 4);
124	            ps.setBigDecimal(4, new BigDecimal("579.90"));
125	            ps.addBatch();
126	
127	            ps.executeBatch();
128	        }
129	    }
