131	    public List<Room> getAllRooms() {
132	        List<Room> rooms = new ArrayList<>();
133	        String sql = "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number";
134	
135	        try (Connection conn = dataSource.getConnection();
136	             Statement stmt = conn.createStatement();
137	             ResultSet rs = stmt.executeQuery(sql)) {
138	
139	            while (rs.next()) {
