178	    public long insertReservation(Reservation reservation) {
179	        String sql = """
180	            INSERT INTO reservations
181	            (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
182	             rate_plan, nights, subtotal, discount, total, status, amount_paid)
183	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
184	            RETURNING id
185	            """;
186	
187	        try (Connection conn = dataSource.getConnection();
188	             PreparedStatement ps = conn.prepareStatement(sql)) {
189	
190	            ps.setInt(1, reservation.getRoomNumber());
191	            ps.setString(2, reservation.getGuestName());
192	            ps.setString(3, reservation.getGuestEmail());
193	            ps.setString(4, reservation.getGuestCpf());
194	            ps.setDate(5, java.sql.Date.valueOf(reservation.getCheckIn()));
195	            ps.setDate(6, java.sql.Date.valueOf(reservation.getCheckOut()));
196	            ps.setInt(7, reservation.getGuests());
197	            ps.setString(8, reservation.getRatePlan().getValue());
198	            ps.setInt(9, reservation.getNights());
199	            ps.setBigDecimal(10, reservation.getSubtotal());
200	            ps.setBigDecimal(11, reservation.getDiscount());
201	            ps.setBigDecimal(12, reservation.getTotal());
202	            ps.setString(13, reservation.getStatus().getValue());
203	            ps.setBigDecimal(14, reservation.getAmountPaid());
204	
205	            try (ResultSet rs = ps.executeQuery()) {
206	                if (rs.next()) {
207	                    return rs.getLong("id");
208	                }
209	            }
210	        } catch (SQLException e) {
211	            throw new RuntimeException("Failed to insert reservation", e);
212	        }
213	
214	        throw new RuntimeException("Failed to insert reservation");
215	    }
