305	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
306	        String sql = """
307	            SELECT COUNT(*) as count FROM reservations
308	            WHERE room_number = ?
309	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
310	            AND NOT (check_out <= ? OR check_in >= ?)
311	            """;
312	
313	        try (Connection conn = dataSource.getConnection();
314	             PreparedStatement ps = conn.prepareStatement(sql)) {
315	
316	            ps.setInt(1, roomNumber);
317	            ps.setDate(2, java.sql.Date.valueOf(checkIn));
318	            ps.setDate(3, java.sql.Date.valueOf(checkOut));
319	
320	            try (ResultSet rs = ps.executeQuery()) {
321	                if (rs.next()) {
322	                    return rs.getInt("count") == 0;
323	                }
324	            }
325	        } catch (SQLException e) {
326	            throw new RuntimeException("Failed to check room availability", e);
327	        }
328	
329	        return false;
330	    }
