332	    public List<Reservation> getReservationsForOccupancyReport(LocalDate date) {
333	        String sql = """
334	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
335	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
336	            FROM reservations
337	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
338	            AND check_in <= ? AND check_out > ?
339	            ORDER BY room_number
340	            """;
341	
342	        List<Reservation> reservations = new ArrayList<>();
343	        try (Connection conn = dataSource.getConnection();
344	             PreparedStatement ps = conn.prepareStatement(sql)) {
345	
346	            ps.setDate(1, java.sql.Date.valueOf(date));
347	            ps.setDate(2, java.sql.Date.valueOf(date));
348	
349	            try (ResultSet rs = ps.executeQuery()) {
350	                while (rs.next()) {
351	                    reservations.add(resultSetToReservation(rs));
352	                }
353	            }
354	        } catch (SQLException e) {
355	            throw new RuntimeException("Failed to fetch occupancy report", e);
356	        }
357	
358	        return reservations;
359	    }
360	
361	    public List<Reservation> getReservationsForRevenueReport(int year, int month) {
362	        String sql = """
363	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
364	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
365	            FROM reservations
366	            WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
367	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
368	            AND amount_paid > 0
369	            ORDER BY check_in, id
370	            """;
371	
372	        List<Reservation> reservations = new ArrayList<>();
373	        try (Connection conn = dataSource.getConnection();
374	             PreparedStatement ps = conn.prepareStatement(sql)) {
375	
376	            ps.setInt(1, year);
377	            ps.setInt(2, month);
378	
379	            try (ResultSet rs = ps.executeQuery()) {
380	                while (rs.next()) {
381	                    reservations.add(resultSetToReservation(rs));
382	                }
383	            }
384	        } catch (SQLException e) {
385	            throw new RuntimeException("Failed to fetch revenue report", e);
386	        }
387	
388	        return reservations;
389	    }
390	
391	    private Reservation resultSetToReservation(ResultSet rs) throws SQLException {
392	        Reservation res = new Reservation(
393	            rs.getLong("id"),
394	            rs.getInt("room_number"),
395	            rs.getString("guest_name"),
396	            rs.getString("guest_email"),
397	            rs.getString("guest_cpf"),
398	            rs.getDate("check_in").toLocalDate(),
399	            rs.getDate("check_out").toLocalDate(),
400	            rs.getInt("guests"),
401	            RatePlan.fromValue(rs.getString("rate_plan")),
402	            rs.getInt("nights"),
403	            rs.getBigDecimal("subtotal"),
404	            rs.getBigDecimal("discount"),
405	            rs.getBigDecimal("total")
406	        );
407	        res.setStatus(ReservationStatus.fromValue(rs.getString("status")));
408	        res.setAmountPaid(rs.getBigDecimal("amount_paid"));
409	        res.setRefund(rs.getBigDecimal("refund"));
410	        return res;
411	    }
412	
413	    public void close() {
414	        dataSource.close();
415	    }
416	}

