335	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
336	            FROM reservations
337	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
338	            AND check_in <= ? AND check_out > ?
339	            ORDER BY room_number
340	            """;
341	
342	        List<Reservation> reservations = new ArrayList<>();
343	        try (Connection conn = dataSource.getConnection();
344	             PreparedStatement ps = conn.prepareStatement(sql)) {
