361	    public List<Reservation> getReservationsForRevenueReport(int year, int month) {
362	        String sql = """
363	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
364	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
365	            FROM reservations
366	            WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
367	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
368	            AND amount_paid > 0
369	            ORDER BY check_in, id
370	            """;
