375	
376	            ps.setInt(1, year);
377	            ps.setInt(2, month);
378	
379	            try (ResultSet rs = ps.executeQuery()) {
380	                while (rs.next()) {
381	                    reservations.add(resultSetToReservation(rs));
382	                }
383	            }
384	        } catch (SQLException e) {
385	            throw new RuntimeException("Failed to fetch revenue report", e);
386	        }
387	
388	        return reservations;
389	    }
