  3	import com.pousadamarealta.domain.*;
  4	import com.pousadamarealta.events.ReservationEventDispatcher;
  5	import com.pousadamarealta.utils.PricingCalculator;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.util.Optional;
 10	
 11	public class ReservationService {
 12	    private final Database database;
 13	    private final ReservationEventDispatcher eventDispatcher;
 14	
 15	    public ReservationService(Database database, ReservationEventDispatcher eventDispatcher) {
 16	        this.database = database;
 17	        this.eventDispatcher = eventDispatcher;
 18	    }
 19	
 20	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 21	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 22	        Optional<Room> room = database.getRoomByNumber(roomNumber);
 23	        if (room.isEmpty()) {
 24	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 25	        }
 26	
 27	        if (guests < 1) {
 28	            throw new IllegalArgumentException("INVALID_REQUEST");
 29	        }
 30	
 31	        if (guests > room.get().getCapacity()) {
 32	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
 33	        }
 34	
 35	        if (!checkIn.isBefore(checkOut)) {
 36	            throw new IllegalArgumentException("INVALID_REQUEST");
 37	        }
 38	
 39	        if (!database.isRoomAvailable(roomNumber, checkIn, checkOut)) {
 40	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 41	        }
 42	
 43	        int nights = PricingCalculator.calculateNights(checkIn, checkOut);
 44	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.get().getNightlyRate(), checkIn, checkOut);
 45	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
 46	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
 47	
 48	        Reservation reservation = new Reservation(
 49	            0,
 50	            roomNumber,
 51	            guestName,
 52	            guestEmail,
 53	            guestCpf,
 54	            checkIn,
 55	            checkOut,
 56	            guests,
 57	            ratePlan,
 58	            nights,
 59	            subtotal,
 60	            discount,
 61	            total
 62	        );
 63	
 64	        long reservationId = database.insertReservation(reservation);
 65	        reservation = new Reservation(
 66	            reservationId,
 67	            roomNumber,
 68	            guestName,
 69	            guestEmail,
 70	            guestCpf,
 71	            checkIn,
 72	            checkOut,
 73	            guests,
 74	            ratePlan,
 75	            nights,
 76	            subtotal,
 77	            discount,
 78	            total
 79	        );
 80	
 81	        return reservation;
 82	    }
 83	
 84	    public Reservation confirmReservation(long reservationId) {
 85	        Optional<Reservation> reservation = database.getReservationById(reservationId);
 86	        if (reservation.isEmpty()) {
 87	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
 88	        }
 89	
 90	        Reservation res = reservation.get();
 91	        if (res.getStatus() != ReservationStatus.PENDING) {
 92	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
 93	        }
 94	
 95	        res.setStatus(ReservationStatus.CONFIRMED);
 96	        res.setAmountPaid(res.getTotal());
 97	        database.updateReservation(res);
 98	
 99	        eventDispatcher.dispatchReservationConfirmed(res);
100	
101	        return res;
102	    }
103	
104	    public Reservation cancelReservation(long reservationId) {
105	        Optional<Reservation> reservation = database.getReservationById(reservationId);
106	        if (reservation.isEmpty()) {
107	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
108	        }
109	
110	        Reservation res = reservation.get();
111	        if (res.getStatus() == ReservationStatus.CHECKED_IN ||
112	            res.getStatus() == ReservationStatus.CHECKED_OUT ||
113	            res.getStatus() == ReservationStatus.CANCELLED) {
114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
115	        }
116	
117	        boolean wasConfirmed = res.getStatus() == ReservationStatus.CONFIRMED;
118	
119	        res.setStatus(ReservationStatus.CANCELLED);
120	
121	        if (wasConfirmed) {
122	            if (res.getRatePlan() == RatePlan.STANDARD) {
123	                res.setRefund(res.getTotal());
124	            } else {
125	                res.setRefund(BigDecimal.ZERO);
126	            }
127	        } else {
128	            res.setRefund(BigDecimal.ZERO);
129	        }
130	
131	        database.updateReservation(res);
132	
133	        if (wasConfirmed) {
134	            eventDispatcher.dispatchReservationCancelled(res);
135	        }
136	
137	        return res;
138	    }
139	
140	    public Reservation checkIn(long reservationId) {
141	        Optional<Reservation> reservation = database.getReservationById(reservationId);
142	        if (reservation.isEmpty()) {
143	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
144	        }
145	
146	        Reservation res = reservation.get();
147	        if (res.getStatus() != ReservationStatus.CONFIRMED) {
148	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
149	        }
150	
151	        res.setStatus(ReservationStatus.CHECKED_IN);
152	        database.updateReservation(res);
153	
154	        return res;
155	    }
156	
157	    public Reservation checkOut(long reservationId) {
158	        Optional<Reservation> reservation = database.getReservationById(reservationId);
159	        if (reservation.isEmpty()) {
160	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
161	        }
162	
163	        Reservation res = reservation.get();
164	        if (res.getStatus() != ReservationStatus.CHECKED_IN) {
165	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
166	        }
167	
168	        res.setStatus(ReservationStatus.CHECKED_OUT);
169	        database.updateReservation(res);
170	
171	        return res;
172	    }
173	}
