201	import com.pousadamarealta.domain.Reservation;
202	import com.pousadamarealta.utils.Formatting;
203	
204	public class DocumentService {
205	    private final Database database;
206	
207	    public DocumentService(Database database) {
208	        this.database = database;
209	    }
210	
211	    public Document createDocument(Reservation reservation) {
212	        var room = database.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
213	        return new Document(
214	            reservation.getId(),
215	            reservation.getGuestName(),
216	            reservation.getGuestCpf(),
217	            reservation.getRoomNumber(),
218	            room.getType(),
219	            reservation.getCheckIn(),
220	            reservation.getCheckOut(),
221	            reservation.getNights(),
222	            reservation.getSubtotal(),
223	            reservation.getDiscount(),
224	            reservation.getTotal()
225	        );
226	    }
227	
228	    public String generateReceiptText(Document document) {
229	        StringBuilder sb = new StringBuilder();
230	        sb.append("Comprovante de reserva nº ").append(document.getReservationId()).append("\n");
231	        sb.append("Hóspede: ").append(document.getGuestName()).append(" (CPF ").append(formatCpf(document.getGuestCpf())).append(")\n");
232	        sb.append("Quarto: ").append(document.getRoomNumber()).append(" (").append(document.getRoomType().getValue()).append(")\n");
233	        sb.append("Entrada: ").append(Formatting.formatDate(document.getCheckIn())).append(" | ");
234	        sb.append("Saída: ").append(Formatting.formatDate(document.getCheckOut())).append(" | ");
235	        sb.append(getNightsLabel(document.getNights())).append("\n");
236	        sb.append("Diárias: ").append(Formatting.formatMoney(document.getSubtotal())).append("\n");
237	
238	        if (document.getDiscount().signum() > 0) {
239	            sb.append("Desconto: ").append(Formatting.formatMoney(document.getDiscount())).append("\n");
240	        }
241	
242	        sb.append("Total: ").append(Formatting.formatMoney(document.getTotal())).append("\n");
243	
244	        return sb.toString();
245	    }
246	
247	    private String getNightsLabel(int nights) {
248	        return nights == 1 ? "1 diária" : nights + " diárias";
249	    }
250	
251	    private String formatCpf(String cpf) {
252	        if (cpf.length() == 11) {
253	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
254	        }
255	        return cpf;
256	    }
257	}
258	package com.pousadamarealta.services;
259	
260	import com.pousadamarealta.domain.Reservation;
261	import com.pousadamarealta.utils.Formatting;
262	
263	import java.math.BigDecimal;
264	import java.time.LocalDate;
265	import java.time.YearMonth;
266	import java.util.List;
267	
268	public class ReportService {
269	    private final Database database;
270	
271	    public ReportService(Database database) {
272	        this.database = database;
273	    }
274	
275	    public String generateOccupancyReport(LocalDate date) {
276	        List<Reservation> reservations = database.getReservationsForOccupancyReport(date);
277	        List<com.pousadamarealta.domain.Room> allRooms = database.getAllRooms();
278	
279	        StringBuilder csv = new StringBuilder();
280	        csv.append("room,type,reservation,check_in,check_out\n");
281	
282	        for (var room : allRooms) {
283	            var reservation = reservations.stream()
284	                .filter(r -> r.getRoomNumber() == room.getNumber())
285	                .findFirst();
286	
287	            if (reservation.isPresent()) {
288	                var res = reservation.get();
289	                csv.append(res.getRoomNumber()).append(",")
290	                   .append(res.getRoomNumber() == 301 ? "SUITE" : (res.getRoomNumber() < 200 ? "STANDARD" : "DELUXE")).append(",")
291	                   .append(res.getId()).append(",")
292	                   .append(Formatting.formatDateIso(res.getCheckIn())).append(",")
293	                   .append(Formatting.formatDateIso(res.getCheckOut())).append("\n");
294	            }
295	        }
296	
297	        int occupiedRooms = (int) reservations.stream()
298	            .map(Reservation::getRoomNumber)
299	            .distinct()
300	            .count();
301	
302	        csv.append("total,").append(occupiedRooms).append("/").append(allRooms.size()).append("\n");
303	
304	        return csv.toString();
305	    }
306	
307	    public String generateRevenueReport(YearMonth yearMonth) {
308	        List<Reservation> reservations = database.getReservationsForRevenueReport(
309	            yearMonth.getYear(),
310	            yearMonth.getMonthValue()
311	        );
312	
313	        StringBuilder csv = new StringBuilder();
314	        csv.append("reservation,room,check_in,check_out,status,amount\n");
315	
316	        BigDecimal total = BigDecimal.ZERO;
317	
318	        for (var res : reservations) {
319	            BigDecimal amount = res.getAmountPaid();
320	            if (res.getRefund() != null) {
321	                amount = amount.subtract(res.getRefund());
322	            }
323	
324	            csv.append(res.getId()).append(",")
325	               .append(res.getRoomNumber()).append(",")
326	               .append(Formatting.formatDateIso(res.getCheckIn())).append(",")
327	               .append(Formatting.formatDateIso(res.getCheckOut())).append(",")
328	               .append(res.getStatus().getValue()).append(",")
329	               .append(Formatting.formatMoneyForCsv(amount)).append("\n");
330	
331	            total = total.add(amount);
332	        }
333	
334	        csv.append("total,,,,").append(Formatting.formatMoneyForCsv(total)).append("\n");
335	
336	        return csv.toString();
337	    }
338	}

