     1	package com.pousadamarealta.utils;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        Month month = date.getMonth();
    14	        int day = date.getDayOfMonth();
    15	
    16	        return (month == Month.DECEMBER && day >= 15) ||
    17	               (month == Month.JANUARY) ||
    18	               (month == Month.FEBRUARY && day <= 28) ||
    19	               month == Month.JULY;
    20	    }
    21	
    22	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    23	        if (isHighSeason(date)) {
    24	            return Formatting.round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
    25	        }
    26	        return baseRate;
    27	    }
    28	
    29	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    30	        BigDecimal subtotal = BigDecimal.ZERO;
    31	        LocalDate current = checkIn;
    32	        while (current.isBefore(checkOut)) {
    33	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, current);
    34	            subtotal = subtotal.add(nightlyRate);
    35	            current = current.plusDays(1);
    36	        }
    37	        return Formatting.round(subtotal);
    38	    }
    39	
    40	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    41	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    42	            return Formatting.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    43	        }
    44	        return BigDecimal.ZERO;
    45	    }
    46	
    47	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    48	        return Formatting.round(subtotal.subtract(discount));
    49	    }
    50	
    51	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    52	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    53	    }
    54	}
