     9	import static org.junit.jupiter.api.Assertions.*;
    10	
    11	public class ReservationSystemTest {
    12	
    13	    @Test
    14	    public void testHighSeasonDetection() {
    15	        assertTrue(PricingCalculator.isHighSeason(LocalDate.of(2027, 12, 15)));
    16	        assertTrue(PricingCalculator.isHighSeason(LocalDate.of(2027, 1, 15)));
    17	        assertTrue(PricingCalculator.isHighSeason(LocalDate.of(2027, 7, 10)));
    18	        assertFalse(PricingCalculator.isHighSeason(LocalDate.of(2027, 4, 10)));
    19	    }
    20	
    21	    @Test
    22	    public void testNightlyRateCalculation() {
    23	        BigDecimal baseRate = new BigDecimal("100.00");
    24	        BigDecimal highSeasonRate = PricingCalculator.calculateNightlyRate(baseRate, LocalDate.of(2027, 7, 10));
    25	        assertEquals(new BigDecimal("120.00"), highSeasonRate);
    26	
    27	        BigDecimal lowSeasonRate = PricingCalculator.calculateNightlyRate(baseRate, LocalDate.of(2027, 4, 10));
    28	        assertEquals(baseRate, lowSeasonRate);
    29	    }
    30	
    31	    @Test
    32	    public void testSubtotalCalculation() {
    33	        BigDecimal baseRate = new BigDecimal("249.90");
    34	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
    35	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
    36	
    37	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(baseRate, checkIn, checkOut);
    38	        assertEquals(new BigDecimal("599.76"), subtotal);
    39	    }
    40	
    41	    @Test
    42	    public void testDiscountCalculation() {
    43	        BigDecimal subtotal = new BigDecimal("1000.00");
    44	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, RatePlan.NON_REFUNDABLE);
    45	        assertEquals(new BigDecimal("150.00"), discount);
    46	
    47	        BigDecimal noDiscount = PricingCalculator.calculateDiscount(subtotal, RatePlan.STANDARD);
    48	        assertEquals(BigDecimal.ZERO, noDiscount);
    49	    }
    50	
    51	    @Test
    52	    public void testNightsCalculation() {
    53	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
    54	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
    55	        int nights = PricingCalculator.calculateNights(checkIn, checkOut);
    56	        assertEquals(2, nights);
    57	    }
    58	}

